sys_script.script:
(function executeRule(current, previous /*null when insert*/) {
    if (current.x_status == 'scheduled' &&
        (previous == null || previous.status != 'scheduled')) {

        var restMsg = new sn_ws.RESTMessageV2('Notify External When Event Scheduled', 'POST');
        restMsg.setStringParameterNoEscape('number', current.getValue('number'));
        restMsg.setStringParameterNoEscape('status', current.getValue('x_status'));
        restMsg.setStringParameterNoEscape('event_name', current.getValue('x_event_name'));

        try {
            var response = restMsg.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();

            gs.info('REST call sent. Status: ' + httpStatus + ', Response: ' + responseBody);
        } catch (ex) {
            gs.error('REST call failed: ' + ex.getMessage());
        }
    }
})(current, previous);
